  "privFooter": "Privasi & penyimpanan",
  "privTitle": "Privasi dan penyimpanan browser",
  "privClose": "Tutup pemberitahuan privasi",
  "privWho": "Siapa yang bertanggung jawab?",
  "privWhat": "Apa yang kami gunakan dan mengapa",
  "privStorage": "Penyimpanan browser",
  "privOther": "Fitur lain yang sudah ada",
  "privProviders": "Penyedia layanan dan transfer internasional",
  "privRetention": "Penyimpanan dan penghapusan data",
  "privRights": "Hak Anda",
  "noticeReopen": "Pemberitahuan penyimpanan",
  "noticeLabel": "Pemberitahuan penyimpanan browser",
  "noticeText": "Cook menggunakan penyimpanan browser untuk fitur memasak dan masuk yang Anda gunakan. Tidak ada penyimpanan untuk iklan atau analitik yang ditambahkan.",
  "noticeClose": "Tutup pemberitahuan penyimpanan",
  "privDraftLabel": "Draf — diperbarui 28 Oktober 2026.",
  "privDraft": "Fitur akun sedang diuji. Detail operator dan layanan di bawah ini harus dilengkapi sebelum peluncuran publik.",
  "privWho1": "Cook dioperasikan oleh [nama resmi dan alamat pos operator]. Hubungi [alamat email privasi] untuk pertanyaan dan permintaan terkait privasi. Detail ini harus dilengkapi sebelum pendaftaran dibuka.",
  "privWhat1": "Saat Anda membuat akun, kami menggunakan email, pengenal akun, catatan autentikasi kata sandi, dan status verifikasi untuk menyediakan dan mengamankan akun Anda. Kata sandi ditangani oleh penyedia autentikasi sebagai hash yang aman; Cook tidak menyimpan kata sandi yang dapat dibaca. Kami menyimpan tata letak dapur, bahasa yang dipilih, tema, dan satuan ukur untuk memulihkan pengaturan Anda di semua perangkat. Email dan kata sandi diperlukan untuk akun; Anda tetap bisa melihat resep tanpa akun.",
  "privWhat2": "Pemrosesan akun dan pengaturan diperlukan untuk menyediakan layanan akun yang Anda minta (GDPR Pasal 6(1)(b)). Catatan terbatas untuk keamanan dan pencegahan penyalahgunaan dapat diproses berdasarkan kepentingan sah (Pasal 6(1)(f)), sejauh diperlukan dan setelah penyeimbangan. Email verifikasi dan atur ulang kata sandi adalah pesan layanan, bukan pemasaran. Fitur akun tidak menambahkan iklan atau analitik.",
  "privStorage1": "Cook menggunakan sessionStorage untuk membawa dapur, kemajuan memasak, dan pilihan Anda antarhalaman di tab yang sama. Saat Anda masuk, ini juga menyimpan sesi autentikasi Anda. Browser biasanya menghapusnya saat sesi tab berakhir, tetapi pemulihan sesi browser dapat mempertahankannya. Keluar akan menghapus data tab Cook. Penutupan pemberitahuan penyimpanan hanya diingat di tab tersebut. Skrip milik Cook sendiri tidak memasang cookie. Penyedia hosting atau layanan Anda mungkin memiliki pemrosesan keamanan sendiri yang harus didokumentasikan sebelum peluncuran.",
  "privStorage2": "OK dan tombol tutup pada pemberitahuan penyimpanan hanya menutup pemberitahuan. Keduanya tidak mengizinkan analitik, iklan, atau pelacakan opsional lainnya. Penyimpanan tidak penting apa pun di masa depan memerlukan pilihan terpisah sebelum dimulai, dengan penolakan dan penarikan yang sama mudahnya.",
  "privOther1": "Fitur suara daftar resep saat ini meminta perkiraan negara dari country.is berdasarkan alamat IP Anda untuk memilih bahasa pengenalan suara. Jika Anda menggunakan pengenalan melalui mikrofon, browser Anda dapat mengirim audio ke penyedia layanan pengenalan suaranya. Anda juga bisa mengetik bahan. Penyedia ini, kebijakan mereka, dan dasar hukum fitur ini harus ditinjau sebelum peluncuran publik.",
  "privProviders1": "Penyedia akun yang direncanakan: Supabase (PostgreSQL dan autentikasi terkelola), dengan wilayah basis data terpilih di UE. Penyedia email: [penyedia]. Hosting situs: [penyedia]. Operator harus mengonfirmasi penyedia sebenarnya, perjanjian pemrosesan, subprosesor, lokasi log, dan setiap transfer ke luar EEA. Wilayah basis data di UE tidak dengan sendirinya mengecualikan transfer internasional. Bila relevan, sebutkan keputusan kecukupan atau perlindungan kontraktual yang berlaku dan cara mendapatkan salinannya.",
  "privRetention1": "Pengaturan akun disimpan selama akun Anda aktif. Anda dapat meminta penghapusan melalui kontak privasi di atas. Sebelum peluncuran, operator harus menetapkan proses tanggapan atas permintaan penghapusan, masa kedaluwarsa akun yang belum diverifikasi, serta periode penyimpanan log keamanan dan cadangan. Data yang dihapus mungkin tetap ada di cadangan dengan akses terbatas hingga periode penyimpanan cadangan yang terdokumentasi berakhir.",
  "privRights1": "Bergantung pada ketentuan yang berlaku, Anda dapat meminta akses, perbaikan, penghapusan, pembatasan, atau portabilitas, atau menolak pemrosesan berdasarkan kepentingan sah. Hubungi operator di atas; permintaan biasanya dijawab dalam satu bulan, dan setiap perpanjangan yang sah akan dijelaskan. Anda dapat mengajukan keluhan ke otoritas pengawas, termasuk NAIH Hongaria di naih.hu. Cook tidak menggunakan pengaturan akun untuk keputusan otomatis yang berdampak hukum atau berdampak signifikan serupa.",
  "favOnly": "Hanya favorit",
