  "Pork shoulder": "Daging leher babi",
  "1 cm pieces": "potongan 1 cm",
  "Whisk the flour, the egg and the salt, then whisk in the milk and the water little by little until smooth.": "Kocok tepung, telur, dan garam, lalu tambahkan susu dan air sedikit demi sedikit sambil dikocok hingga adonan halus.",
  "Finely chop the onion; chop the tomato and the pepper.": "Cincang halus bawang bombai; cincang tomat dan paprika.",
  "Cut the meat": "Potong daging",
  "Cut the meat into 1 cm pieces.": "Potong daging menjadi potongan 1 cm.",
  "Heat the oil in the saucepan and cook the onion until soft and golden.": "Panaskan minyak di panci kecil dan tumis bawang bombai hingga lunak dan keemasan.",
  "Paprika and meat": "Paprika dan daging",
  "Take the pan off the heat and stir in the paprika. Add the meat, the tomato, the pepper, the salt and the water.": "Angkat panci kecil dari api dan aduk paprika bubuk. Masukkan daging, tomat, paprika, garam, dan air.",
  "Meat in the red sauce": "Daging dalam saus merah",
  "Stew": "Masak perlahan",
  "Cover and simmer gently until the meat is tender.": "Tutup dan masak perlahan hingga daging empuk.",
  "Meat tender": "Daging empuk",
  "Lift out the meat": "Angkat daging",
  "Lift the meat out with a slotted spoon onto the board; keep the juice in the pan.": "Pindahkan daging ke talenan dengan sendok berlubang; biarkan kuahnya di panci.",
  "Juice left in the pan": "Kuah di panci",
  "Chop the meat finely and mix it with 2 tablespoons of the sour cream and a spoonful of the juice.": "Cincang halus daging dan campur dengan 2 sendok makan krim asam dan satu sendok kuah.",
  "Juicy filling": "Isian juicy",
  "Heat the frying pan and wipe it with a little oil.": "Panaskan wajan dan olesi dengan sedikit minyak.",
  "Pour in a small ladle of batter and tilt the pan so it covers the bottom thinly. When the edge lifts (about 1 min), flip and cook 30 seconds. About 2 crêpes per person.": "Tuang satu sendok sayur kecil adonan dan miringkan wajan untuk melapisi dasarnya tipis-tipis. Saat pinggirnya terlepas (sekitar 1 menit), balik dan masak 30 detik. Sekitar 2 crepe per orang.",
  "Whisk the rest of the sour cream with the flour, stir it into the juice with a splash of water and simmer 2 to 3 minutes until creamy.": "Kocok sisa krim asam dengan tepung, aduk ke dalam kuah dengan sedikit air, dan didihkan 2–3 menit hingga creamy.",
  "Creamy, pourable": "Creamy, melapisi sendok",
  "Put a spoonful of filling on each crêpe, fold in the sides and roll it up. Lay them side by side in the baking dish.": "Letakkan satu sendok isian di setiap crepe, lipat sisinya, dan gulung. Susun rapat berdampingan di pinggan tahan panas.",
  "All rolled": "Semua tergulung",
  "Sauce and bake": "Siram dan panggang",
  "Pour the sauce over the crêpes and bake until bubbling.": "Siram saus ke atas crepe dan panggang hingga meletup-letup.",
  "Bubbling sauce": "Saus meletup-letup",
  "Serve hot, with a spoonful of the sauce and chopped parsley on top.": "Sajikan panas dengan satu sendok saus dan peterseli cincang di atasnya.",
  "Chop the vegetables · Cut the meat": "Potong sayuran · Potong daging",
  "Soften the onion … Lift out the meat": "Layukan bawang bombai … Angkat daging",
