  "cut into thigh and drumstick": "dipotong menjadi paha atas dan paha bawah",
  "Cut the chicken": "Potong ayam",
  "Cut the legs at the joint into thighs and drumsticks. Pat dry and sprinkle with the salt and pepper.": "Potong paha ayam di sendinya menjadi paha atas dan paha bawah. Keringkan dan taburi garam dan merica.",
  "Cut and seasoned": "Dipotong dan dibumbui",
  "Melt the lard in the saucepan and cook the onion until soft and golden.": "Lelehkan lemak babi di panci kecil dan tumis bawang bombai hingga lunak dan keemasan.",
  "Take the pan off the heat, stir in the paprika and add a splash of the water at once so the paprika doesn't burn.": "Angkat panci kecil dari api, aduk paprika bubuk, dan segera tambahkan sedikit air agar paprika tidak gosong.",
  "Add the chicken and turn it in the paprika. Add the tomato, the pepper and the rest of the water.": "Masukkan ayam dan gulingkan di paprika. Masukkan tomat, paprika, dan sisa air.",
  "Chicken coated": "Ayam terbalut",
  "Cover and simmer gently, turning the chicken once, until it is tender and comes away from the bone.": "Tutup dan masak perlahan, balik ayam sekali, hingga empuk dan lepas dari tulang.",
  "Tender at the bone": "Lepas dari tulang",
  "Make the nokedli dough": "Buat adonan nokedli",
  "Mix the flour, the eggs, the salt and the water into a thick, sticky dough that drops slowly from the spoon. Beat until smooth.": "Campur tepung, telur, garam, dan air menjadi adonan kental dan lengket yang jatuh perlahan dari sendok. Kocok hingga halus.",
  "Thick, sticky, smooth": "Kental, lengket, halus",
  "Let the dough rest so it becomes smooth.": "Diamkan adonan agar menjadi halus.",
  "Make the nokedli": "Buat nokedli",
  "Set the spaetzle maker over the boiling water, fill the box with dough and slide it back and forth. Work in 2 or 3 batches.": "Letakkan parutan spätzle di atas air mendidih, isi wadahnya dengan adonan, dan geser maju mundur. Lakukan dalam 2–3 tahap.",
  "Dough all in the water": "Semua adonan di air",
  "Cook until they float": "Rebus hingga mengapung",
  "Boil until the nokedli float, then 1 more minute.": "Rebus hingga nokedli mengapung, lalu 1 menit lagi.",
  "Drain and toss": "Tiriskan dan lumuri",
  "Drain the nokedli in a colander, rinse quickly with hot water and toss with the butter or oil so they don't stick.": "Tiriskan nokedli di saringan, bilas cepat dengan air panas, dan aduk dengan mentega atau minyak agar tidak lengket.",
  "Loose, not sticky": "Terpisah, tidak lengket",
  "Whisk the sour cream and the flour smooth in a bowl.": "Kocok krim asam dan tepung di mangkuk hingga halus.",
  "Thicken the sauce": "Kentalkan saus",
  "Lift out the chicken. Stir a ladle of the hot sauce into the sour cream mix, then stir it all into the pan. Simmer 3 minutes and put the chicken back.": "Angkat ayam. Aduk satu sendok sayur saus panas ke dalam campuran krim asam dan tuang semuanya kembali ke panci kecil. Didihkan 3 menit dan masukkan kembali ayam.",
  "Creamy, coats the spoon": "Creamy, melapisi sendok",
  "Serve the chicken and plenty of sauce with the nokedli.": "Sajikan ayam dengan banyak saus dan nokedli.",
  "Cut the chicken · Chop the vegetables": "Potong ayam · Potong sayuran",
  "Soften the onion … Thicken the sauce": "Layukan bawang bombai … Kentalkan saus",
  "Make the nokedli dough · Rest the dough": "Buat adonan nokedli · Diamkan adonan",
  "Boil the water … Cook until they float": "Didihkan air … Rebus hingga mengapung",
  "Wet the chopping board and spread some dough near its edge. Hold it over the pot and scrape thin strips into the boiling water with a wet knife, dipping the knife in the water as you go. Work in batches.": "Basahi talenan dan ratakan sedikit adonan di dekat tepinya. Pegang di atas panci dan kerok potongan tipis ke air mendidih dengan pisau basah, celupkan pisau ke air sesekali. Lakukan dalam beberapa tahap.",
  "Sausage": "Sosis",
