  "Cut the peppers": "Potong paprika",
  "Remove the stems and seeds and cut the peppers into 1 cm rings.": "Buang tangkai dan bijinya, lalu potong paprika menjadi cincin 1 cm.",
  "Cut into rings": "Berbentuk cincin",
  "Cut the tomatoes": "Potong tomat",
  "Cut the tomatoes into chunks.": "Potong tomat menjadi beberapa bagian.",
