  "Heat the oil in the large frying pan and cook the onion until soft and glassy.": "Panaskan minyak di wajan besar dan tumis bawang bombai hingga lunak dan bening.",
  "Soft, glassy": "Lunak, bening",
  "Peppers in": "Masukkan paprika",
  "Take the pan off the heat for a moment, stir in the paprika, then add the peppers. Cook, stirring now and then, until they soften and lose their bright colour.": "Angkat wajan dari api sebentar, aduk paprika bubuk, lalu masukkan paprika. Masak sambil sesekali diaduk hingga paprika layu dan warnanya tidak cerah lagi.",
  "Peppers soft": "Paprika lunak",
  "Add the tomatoes, the salt and the sugar. Simmer uncovered until the tomatoes fall apart and most of the liquid is gone.": "Masukkan tomat, garam, dan gula. Masak tanpa tutup hingga tomat hancur dan sebagian besar cairannya menguap.",
