  "Turn the oven on to 180 °C conventional (160 °C fan). Line the baking tray with baking paper.": "Nyalakan oven 180 °C api atas-bawah (160 °C kipas). Alasi loyang dengan kertas roti.",
  "Oven on, tray lined": "Oven menyala, loyang dialasi",
  "Soak the raisins": "Rendam kismis",
  "Put the raisins in a small bowl and pour half the rum over them (or a little warm water).": "Masukkan kismis ke mangkuk kecil dan siram dengan setengah rum (atau sedikit air hangat).",
  "Soaking": "Sedang direndam",
  "Separate the eggs": "Pisahkan telur",
  "Separate the eggs for the sponge: whites into a clean bowl, yolks into another.": "Pisahkan telur untuk bolu: putih telur ke mangkuk bersih, kuning telur ke mangkuk lain.",
  "Separated": "Dipisahkan",
  "Whisk the whites": "Kocok putih telur",
  "Whisk the whites to soft peaks, then add half the sugar a little at a time and whisk until stiff and glossy.": "Kocok putih telur hingga soft peak, lalu tambahkan setengah gula sedikit demi sedikit dan kocok hingga kaku dan mengilap.",
  "Stiff, glossy peaks": "Kaku dan mengilap",
  "Yolks in": "Masukkan kuning telur",
