  "Walnut and cocoa": "Kenari dan kakao",
  "Divide the batter in two bowls. Fold the ground walnuts into one and the cocoa into the other.": "Bagi adonan ke dua mangkuk. Aduk kenari giling ke satu mangkuk dan kakao ke mangkuk lainnya.",
  "Two batters": "Dua adonan",
  "Spread on the tray": "Ratakan di loyang",
  "Fold a ridge in the middle of the baking paper and spread the walnut batter on one half, the cocoa batter on the other, about 1 cm thick.": "Buat lipatan di tengah kertas roti dan ratakan adonan kenari di satu sisi dan adonan kakao di sisi lainnya, setebal sekitar 1 cm.",
  "Evenly spread": "Rata merata",
  "Bake the sponge": "Panggang bolu",
  "Bake until springy and a toothpick comes out clean.": "Panggang hingga bolu kembali saat ditekan dan tusuk gigi keluar bersih.",
  "Springy, toothpick clean": "Mengembang, tusuk gigi bersih",
  "Cool the sponge": "Dinginkan bolu",
  "Let the sponge cool on the rack.": "Biarkan bolu dingin di rak kawat.",
  "Custard base": "Dasar krim",
  "Whisk the yolks, the sugar and the flour smooth with a few spoons of the milk. Heat the rest of the milk in the saucepan until it steams.": "Kocok kuning telur, gula, dan tepung dengan beberapa sendok susu hingga halus. Panaskan sisa susu di panci kecil hingga beruap.",
  "Smooth base, milk steaming": "Dasar halus, susu beruap",
  "Cook the custard": "Masak krim",
  "Pour the hot milk onto the yolks while whisking, pour it all back into the pan and cook on low, whisking all the time, until thick. Stir in the vanilla.": "Tuang susu panas ke kuning telur sambil dikocok, kembalikan semuanya ke panci, lalu masak dengan api kecil sambil terus dikocok hingga mengental. Aduk vanili.",
  "Thick, coats the whisk": "Kental, melapisi pengocok",
  "Cool the custard": "Dinginkan krim",
  "Pour into a bowl, press cling film onto the surface and let it cool.": "Pindahkan ke mangkuk, tempelkan plastik wrap langsung di permukaannya, dan biarkan dingin.",
  "Cool, no skin": "Dingin, tanpa lapisan kulit",
  "Make the syrup": "Buat sirup",
  "Boil the water and the sugar with the lemon zest for 2 minutes. Take off the heat and add the rest of the rum.": "Rebus air dan gula dengan kulit lemon selama 2 menit. Angkat dari api dan tambahkan sisa rum.",
  "Syrupy": "Bersirup",
  "Chop the walnuts": "Cincang kenari",
  "Roughly chop the walnuts for the layers.": "Cincang kasar kenari untuk lapisan.",
  "Tear the sponges into rough pieces. In a deep dish, layer the walnut sponge, half the syrup, half the custard, half the raisins and walnuts; then the cocoa sponge, the rest of the syrup, raisins and walnuts, and finish with the custard.": "Sobek bolu menjadi potongan kasar. Di pinggan dalam, susun berlapis bolu kenari, setengah sirup, setengah krim, setengah kismis dan kenari; lalu bolu kakao, sisa sirup, kismis, dan kenari, dan akhiri dengan krim.",
  "Cover and chill for at least 4 hours; overnight is best.": "Tutup dan dinginkan di kulkas minimal 4 jam; paling baik semalaman.",
  "Set and cold": "Set dan dingin",
